const $ = (s, el=document)=>el.querySelector(s);
const $$ = (s, el=document)=>[...el.querySelectorAll(s)];
const state={page:'home',products:[],stores:[],favorites:[],cart:JSON.parse(localStorage.getItem('collectra_cart')||'[]'),device:localStorage.getItem('collectra_device')||crypto.randomUUID(),selectedCategory:'All',selectedStore:null,verifyFiles:{},evidenceContext:null,evidenceBlob:null,evidenceReviewUrl:'',evidenceRecorder:null,evidenceStream:null,evidenceChunks:[],evidenceStep:0,evidenceStartedAt:0,evidencePolling:null,evidenceChecking:false,adminKey:localStorage.getItem('collectra_admin_key')||'',sellerSession:localStorage.getItem('collectra_seller_session')||'',buyerSession:localStorage.getItem('collectra_buyer_session')||'',_buyer:null,lang:localStorage.getItem('collectra_lang')||'en'};

const I18N={
en:{nav_home:'Home',nav_shops:'Shops',nav_verify:'Verify Card',nav_sell:'Sell',nav_support:'Support',nav_saved:'Saved',nav_profile:'Profile',nav_cart:'Cart',
hero_title_1:'Collect. Verify.',hero_title_2:'Trade with Confidence.',hero_p:'Collectra is a mobile-first marketplace for collectible cards with verified stores, guided AI-assisted card checks, saved favorites, secure transaction evidence, and human support when you need it.',hero_btn_shops:'Explore Shops',hero_btn_verify:'Verify a Card',
marketplace:'Marketplace',marketplace_p:'Real cards from ID-verified sellers.',
verify_title:'Verify Your Card',verify_p:'Front and back are required. Edges and surface close-ups are optional.',
sell_title:'Sell on Collectra',orders_title:'Orders',seller_orders_title:'Seller Orders',support_title:'Collectra Support',admin_title:'Collectra Admin',shops_title:'Shops',cart_title:'Cart',profile_title:'Profile'},
th:{nav_home:'หน้าแรก',nav_shops:'ร้านค้า',nav_verify:'ตรวจการ์ด',nav_sell:'ขายของ',nav_support:'ช่วยเหลือ',nav_saved:'รายการโปรด',nav_profile:'โปรไฟล์',nav_cart:'ตะกร้า',
hero_title_1:'สะสม ตรวจสอบ',hero_title_2:'ซื้อขายอย่างมั่นใจ',hero_p:'Collectra คือตลาดซื้อขายการ์ดสะสมบนมือถือ พร้อมร้านค้าที่ยืนยันตัวตน ตรวจสอบการ์ดด้วย AI แบบมีขั้นตอนนำทาง บันทึกรายการโปรด หลักฐานการทำธุรกรรมที่ปลอดภัย และทีมงานมนุษย์พร้อมช่วยเหลือเมื่อคุณต้องการ',hero_btn_shops:'ดูร้านค้า',hero_btn_verify:'ตรวจสอบการ์ด',
marketplace:'ตลาดซื้อขาย',marketplace_p:'การ์ดจริงจากผู้ขายที่ยืนยันตัวตนแล้ว',
verify_title:'ตรวจสอบการ์ดของคุณ',verify_p:'ต้องใช้ภาพด้านหน้าและด้านหลัง ส่วนภาพขอบมุมและพื้นผิวจะอัปโหลดหรือไม่ก็ได้',
sell_title:'ขายของบน Collectra',orders_title:'คำสั่งซื้อ',seller_orders_title:'คำสั่งซื้อของผู้ขาย',support_title:'ศูนย์ช่วยเหลือ Collectra',admin_title:'ผู้ดูแลระบบ Collectra',shops_title:'ร้านค้า',cart_title:'ตะกร้าสินค้า',profile_title:'โปรไฟล์'}
};
function t(key){return (I18N[state.lang]&&I18N[state.lang][key])||I18N.en[key]||key}
function toggleLang(){state.lang=state.lang==='en'?'th':'en';localStorage.setItem('collectra_lang',state.lang);render()}
function logoMark(){return `<svg viewBox="0 0 225 66" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Collectra"><path d="M43.53,39.91 A17,17 0 1 1 43.53,26.09" stroke="#8fb7e8" stroke-width="8" fill="none" stroke-linecap="round"/><path d="M45.5 14.5 L47.7 19.3 L52.5 21.5 L47.7 23.7 L45.5 28.5 L43.3 23.7 L38.5 21.5 L43.3 19.3 Z" fill="#f0c96b"/><text x="64" y="39" font-family="system-ui,-apple-system,'Segoe UI',sans-serif" font-weight="500" font-size="23" letter-spacing="2.5" fill="#5b7396">COLLECTRA</text></svg>`}
localStorage.setItem('collectra_device',state.device);

const icons={home:'⌂',shops:'▦',sell:'＋',saved:'♡',profile:'◎',verify:'✓',search:'⌕',cart:'🛒'};
const money=n=>'฿'+Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const api=async(url,opts={})=>{const h={...(opts.headers||{})};if(!h.Authorization){if(state.buyerSession)h.Authorization='Bearer '+state.buyerSession;else if(state.sellerSession&&/^\/api\/(verify|evidence-step-check)/.test(url))h.Authorization='Bearer '+state.sellerSession}const r=await fetch(url,{...opts,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok){if(d.code==='email_unverified'&&state._buyer)state._buyer.email_verified=false;if(r.status===401&&d.error==='Please log in to continue'&&!opts.quiet)buyerExpire();throw new Error(d.error||'Request failed')}return d};
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2400)}
function saveCart(){localStorage.setItem('collectra_cart',JSON.stringify(state.cart))}
function setPage(p){state.page=p;location.hash=p;render()}

async function bootstrap(){
  await refreshBuyer();
  try{
    [state.products,state.stores,state.favorites]=await Promise.all([
      api('/api/products'),api('/api/stores'),(state.buyerSession?api('/api/favorites',{quiet:true}).catch(()=>[]):Promise.resolve([]))
    ]);
  }catch(e){console.error(e);toast('Could not load data')}
  const hash=location.hash.replace('#',''); if(hash)state.page=hash; render();
  if((location.protocol==='https:'||location.hostname==='localhost')&&'serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}
}
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p){state.page=p;render()}});

function header(){return `
<header class="desktop-top">
  <button class="brand ghost" onclick="setPage('home')">${logoMark()}</button>
  <nav class="desktop-links">
    <button onclick="setPage('home')">${t('nav_home')}</button><button onclick="setPage('shops')">${t('nav_shops')}</button><button onclick="setPage('verify')">${t('nav_verify')}</button><button onclick="setPage('sell')">${t('nav_sell')}</button><button onclick="setPage('support')">${t('nav_support')}</button>
  </nav>
  <div class="top-actions"><button class="ghost lang-toggle" onclick="toggleLang()" title="Switch language">${state.lang==='en'?'TH':'EN'}</button><button class="ghost" onclick="setPage('cart')">${t('nav_cart')} (${state.cart.reduce((a,b)=>a+b.qty,0)})</button><button class="btn btn-blue" onclick="setPage('profile')">${t('nav_profile')}</button></div>
</header>`}
function mobileNav(){const cartCount=state.cart.reduce((a,b)=>a+b.qty,0);return `<button class="floating-verify" onclick="setPage('verify')">✓</button><nav class="mobile-nav">
${[['home','nav_home'],['shops','nav_shops'],['cart','nav_cart'],['sell','nav_sell'],['saved','nav_saved'],['profile','nav_profile']].map(([p,key])=>`<button class="${state.page===p?'active':''}" onclick="setPage('${p}')"><span class="nav-icon">${icons[p]}${p==='cart'&&cartCount?`<span class="nav-badge">${cartCount}</span>`:''}</span>${t(key)}</button>`).join('')}
</nav>`}
function shell(content){return `<div class="app-shell">${header()}<main class="page">${content}</main>${mobileNav()}</div>`}

function feature(icon,title,text){return `<div class="feature-card"><div class="feature-icon">${icon}</div><h3>${title}</h3><p>${text}</p></div>`}
function home(){
  const cats=['All','K-pop','T-pop','Other']; const filtered=state.selectedCategory==='All'?state.products:state.products.filter(p=>p.category===state.selectedCategory);
  return shell(`
  <section class="hero"><h1>${t('hero_title_1')}<br><em>${t('hero_title_2')}</em></h1><p>${t('hero_p')}</p><div class="hero-actions"><button class="btn btn-primary" onclick="setPage('shops')">${t('hero_btn_shops')}</button><button class="btn btn-white" onclick="setPage('verify')">${t('hero_btn_verify')}</button></div></section>
  <div class="feature-grid">${feature('✓','AI Verification','Guided front, back and detail photos.')}${feature('♡','Favorites','Save cards and stores for later.')}${feature('★','Verified Shops','Reviews, ratings and verification badges.')}${feature('💬','AI + Human Support','Start with AI, escalate to an admin.')}</div>
  <div class="section-head"><div><h2>${t('marketplace')}</h2><p>${t('marketplace_p')}</p></div></div>
  <div class="chips">${cats.map(c=>`<button class="chip ${state.selectedCategory===c?'active':''}" onclick="state.selectedCategory='${c}';render()">${c}</button>`).join('')}</div>
  <div class="product-grid" style="margin-top:14px">${filtered.map(productCard).join('')||`<div class="empty"><strong>${L('No listings yet','ยังไม่มีสินค้า')}</strong><p>${L('Collectra is just opening. Sellers are joining now, so check back soon, or become one of the first sellers.','Collectra เพิ่งเปิดให้บริการ ผู้ขายกำลังทยอยเข้ามา กลับมาดูใหม่เร็วๆ นี้ หรือเป็นหนึ่งในผู้ขายกลุ่มแรก')}</p><button class="btn btn-blue" onclick="setPage('sell')">${L('Become a Seller','สมัครเป็นผู้ขาย')}</button></div>`}</div>
  `)}
function isFav(id){return state.favorites.some(p=>p.id===id)}
function productCard(p){return `<article class="product-card" onclick="openProduct(${p.id})"><div class="product-image-wrap"><img src="${p.image_url||'/assets/placeholder-card.svg'}" alt="${esc(p.title)}"><button class="heart ${isFav(p.id)?'active':''}" onclick="event.stopPropagation();toggleFavorite(${p.id})">${isFav(p.id)?'♥':'♡'}</button></div><div class="product-info"><h3>${esc(p.title)}</h3><div class="sub">${esc(p.store_name||'Store')} ${p.store_verified?'<span class="badge">✓ Verified</span>':''}</div><div class="price">${money(p.price)}</div><div class="stock">${p.stock} in stock</div></div></article>`}
async function toggleFavorite(id){if(needBuyer())return;await api('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:id})});state.favorites=await api('/api/favorites');render();toast('Saved items updated')}
function openProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return; const wrap=document.createElement('div');wrap.className='bottom-sheet-backdrop';wrap.innerHTML=`<div class="bottom-sheet"><div class="sheet-handle"></div><img class="detail-image" src="${p.image_url}" alt=""><div class="section-head"><div><h2>${esc(p.title)}</h2><p>${esc(p.category)} · ${esc(p.condition)}</p></div><button class="heart ${isFav(p.id)?'active':''}" onclick="toggleFavorite(${p.id});this.closest('.bottom-sheet-backdrop').remove()">${isFav(p.id)?'♥':'♡'}</button></div><div class="detail-price">${money(p.price)}</div><p>${esc(p.description||'')}</p><div class="notice ${p.store_verified?'good':'warn'}">${p.store_verified?'✓ Verified shop':'Seller is not yet verified'} · ${esc(p.store_name)}</div><div class="hero-actions"><button class="btn btn-primary" onclick="addCart(${p.id});this.closest('.bottom-sheet-backdrop').remove()">Add to Cart</button><button class="btn btn-blue" onclick="viewStore(${p.store_id});this.closest('.bottom-sheet-backdrop').remove()">View Store</button></div></div>`;wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};document.body.appendChild(wrap)}
function addCart(id){const found=state.cart.find(x=>x.product_id===id);if(found)found.qty++;else state.cart.push({product_id:id,qty:1});saveCart();render();toast('Added to cart')}

function shops(){return shell(`<div class="section-head"><div><h1 class="screen-title">Verified Shops</h1><p>Open a store to see ratings, reviews and live listings.</p></div></div><div class="store-grid">${state.stores.map(storeCard).join('')||`<div class="empty"><strong>${L('No shops yet','ยังไม่มีร้านค้า')}</strong><p>${L('Shops appear here once sellers pass ID verification.','ร้านค้าจะแสดงที่นี่เมื่อผู้ขายผ่านการยืนยันตัวตน')}</p><button class="btn btn-blue" onclick="setPage('sell')">${L('Become a Seller','สมัครเป็นผู้ขาย')}</button></div>`}</div>`)}
function storeCard(s){return `<article class="store-card" onclick="viewStore(${s.id})"><div class="store-cover"><img src="${s.logo_url||'/assets/placeholder-store.svg'}" alt=""></div><div class="store-body"><div class="store-title"><div><h3 style="margin:0">${esc(s.name)}</h3><div class="sub">${esc(s.category)}</div></div>${s.verified?'<span class="verified">✓ Verified</span>':''}</div><p>${esc(s.description)}</p><div class="rating">★ ${s.rating||'New'} <span class="sub">(${s.review_count||0} reviews)</span></div></div></article>`}
async function viewStore(id){state.selectedStore=await api('/api/store?id='+id);state.page='store';render()}
function storePage(){const s=state.selectedStore;if(!s)return shops();return shell(`<button class="ghost" onclick="setPage('shops')">← Shops</button><div class="grid-2" style="margin-top:10px"><section class="panel blue"><h1>${esc(s.name)}</h1><p>${esc(s.description)}</p><div>${s.verified?'<span class="badge">✓ Collectra Verified</span>':'Not verified'}</div><h2>★ ${s.rating||'New'}</h2><p>${s.review_count} reviews</p></section><section class="panel yellow"><h2>Leave a Review</h2>${!state.buyerSession?`<p>${L('Only buyers who paid for an order from this shop can leave a review.','เฉพาะผู้ซื้อที่ชำระเงินสั่งซื้อสินค้าจากร้านนี้เท่านั้นที่รีวิวได้')}</p><button class="btn btn-blue" onclick="state._afterLogin='store';setPage('buyer-login')">${L('Log in to review','เข้าสู่ระบบเพื่อรีวิว')}</button>`:`<p class="sub">${L('Only buyers who paid for an order from this shop can review. One review per shop; posting again updates it.','เฉพาะผู้ซื้อที่ชำระเงินแล้วเท่านั้นที่รีวิวได้ รีวิวได้ร้านละ 1 ครั้ง หากโพสต์ซ้ำจะเป็นการแก้ไข')}</p><div class="form-grid"><div class="field"><label>Rating</label><select id="reviewRating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="field"><label>Review</label><textarea id="reviewText" placeholder="How was your experience?"></textarea></div><button class="btn btn-blue" onclick="submitReview(${s.id})">Post Review</button></div>`}</section></div><div class="section-head"><div><h2>Listings</h2><p>${s.products.length} current products</p></div></div><div class="product-grid">${s.products.map(productCard).join('')||'<div class="empty">No stock yet.</div>'}</div><div class="section-head"><div><h2>Reviews</h2></div></div><div class="panel">${s.reviews.map(r=>`<div class="admin-row"><div class="grow"><strong>${'★'.repeat(r.rating)}</strong> <span class="sub">${esc(r.author||'')} · ${L('Verified buyer','ผู้ซื้อที่ยืนยันแล้ว')}</span><div>${esc(r.text)}</div></div><small>${new Date(r.created_at).toLocaleDateString()}</small></div>`).join('')||'No reviews yet.'}</div>`)}
async function submitReview(store_id){if(needBuyer('store')||needVerified())return;const rating=Number($('#reviewRating').value),text=$('#reviewText').value;await api('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({store_id,rating,text})});toast('Review posted');viewStore(store_id)}

function verify(){return shell(`<div class="section-head"><div><h1 class="screen-title">Verify Your Card</h1><p>Front and back are required. Edges and surface close-ups are optional, but they help the AI be more sure.</p></div></div><div class="grid-2"><section class="panel blue"><h2>Photo guide</h2><div class="photo-guide verify-guide-grid">${guide('1','Front','Full card, flat and centered')}${guide('2','Back','Full back, all corners visible')}${guide('3','Edges & corners (optional)','Close-up of borders and corners')}${guide('4','Surface details (optional)','Logo, print, foil or texture')}</div><div class="notice warn" style="margin-top:14px"><strong>Keep the same card throughout.</strong><br>Use good light, avoid glare, keep every image sharp, and do not crop out edges.</div></section><section class="panel"><div class="form-grid"><div class="field"><label>Category</label><select id="vCategory"><option>K-pop</option><option>T-pop</option><option>Other</option></select></div><div class="field"><label>Card name / set (optional)</label><input id="vName" placeholder="Artist, member, set or card name"></div>${verifyUpload('front','1. Front photo *')}${verifyUpload('back','2. Back photo *')}${verifyUpload('edges','3. Edges & corners detail (optional)')}${verifyUpload('surface','4. Surface / logo / foil detail (optional)')}<div class="progress"><span id="verifyProgress"></span></div><button class="btn btn-primary btn-full" onclick="submitVerification(this)">Start Verification</button><div class="sub">Images are compressed on your phone before upload to reduce waiting time.</div></div></section></div><div id="verifyResult" style="margin-top:18px"></div>`) }
function verifyUpload(kind,label){return `<div class="field required-upload"><label>${label}</label><input id="${kind}Input" type="file" accept="image/*" capture="environment" onchange="handleVerifyFile('${kind}',this.files[0])"></div><div id="${kind}Preview"></div>`}
function guide(n,t,d){return `<div class="guide-card"><div class="guide-icon">${n}</div><div><strong>${t}</strong><div class="sub">${d}</div></div></div>`}
async function compressImage(file,max=1600,quality=.82){if(!file)return null;try{const img=await createImageBitmap(file);const scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);const blob=await new Promise(res=>c.toBlob(res,'image/jpeg',quality));return new File([blob],(file.name.replace(/\.[^.]+$/,'')||'card')+'.jpg',{type:'image/jpeg'})}catch{return file}}
async function handleVerifyFile(kind,file){if(!file)return;state.verifyFiles[kind]=await compressImage(file);const url=URL.createObjectURL(state.verifyFiles[kind]);const el=$('#'+kind+'Preview');if(el)el.innerHTML=`<div class="capture-ok"><img class="preview-img" src="${url}"><span>✓ ${kind==='edges'?'Edges / corners':kind==='surface'?'Surface details':kind[0].toUpperCase()+kind.slice(1)} captured</span></div>`}
async function submitVerification(btn){if(!state.buyerSession&&!state.sellerSession&&needBuyer('verify'))return;if(state.buyerSession&&needVerified())return;const required=[['front','front'],['back','back']];const missing=required.filter(([key])=>!state.verifyFiles[key]).map(([,label])=>label);if(missing.length)return toast('Required: '+missing.join(', '));btn.disabled=true;btn.textContent='Checking your photos…';const prog=$('#verifyProgress');prog.style.width='20%';const fd=new FormData();fd.append('category',$('#vCategory').value);fd.append('card_name',$('#vName').value);['front','back','edges','surface'].forEach(key=>{if(state.verifyFiles[key])fd.append(key,state.verifyFiles[key])});let timer=setInterval(()=>{let w=parseInt(prog.style.width)||20;prog.style.width=Math.min(90,w+5)+'%'},450);try{const r=await api('/api/verify',{method:'POST',body:fd});clearInterval(timer);prog.style.width='100%';const bad=r.verdict==='Suspicious'||r.verdict==='Likely Counterfeit'||r.verdict==='Likely Fake'
const cls=r.verdict==='Likely Authentic'?'good':bad?'bad':'warn';$('#verifyResult').innerHTML=`<div class="result-card"><div class="result-head"><div class="result-icon">${r.verdict==='Likely Authentic'?'✓':(r.verdict==='Likely Counterfeit'||r.verdict==='Likely Fake')?'✕':r.verdict==='Suspicious'?'!':'?'}</div><div><h2 style="margin:0">${esc(r.verdict)}</h2><div class="sub">${esc(r.details?.verdict_th||'')}${r.details?.verdict_th?' · ':''}${esc(r.provider)}</div></div><div class="grow"></div><div class="score">${r.confidence}<small>/100</small></div></div><p>${esc(r.summary)}</p><div class="notice ${cls}">${(r.details?.checks||r.details?.issues||[]).map(x=>'• '+esc(x)).join('<br>')||'All required views were received.'}</div><div class="hero-actions"><button class="btn btn-blue" onclick="setPage('support')">Ask AI Support</button><button class="btn btn-outline" onclick="requestHuman('Please manually review my latest card verification result.')">Request Human Review</button></div></div>`}catch(e){clearInterval(timer);toast(e.message)}finally{btn.disabled=false;btn.textContent='Start Verification'}}

function saved(){if(!state.buyerSession)return shell(`<div class="section-head"><div><h1 class="screen-title">${L('My Favorites','รายการโปรด')}</h1></div></div><div class="empty"><div class="big">♡</div><h2>${L('Log in to see your favorites','เข้าสู่ระบบเพื่อดูรายการโปรด')}</h2><button class="btn btn-blue" onclick="state._afterLogin='saved';setPage('buyer-login')">${L('Log In','เข้าสู่ระบบ')}</button></div>`);return shell(`<div class="section-head"><div><h1 class="screen-title">My Favorites</h1><p>Cards you saved for later.</p></div></div>${state.favorites.length?`<div class="product-grid">${state.favorites.map(productCard).join('')}</div>`:'<div class="empty"><div class="big">♡</div><h2>No saved cards yet</h2><p>Tap the heart on a listing.</p></div>'}`)}
const L=(en,th)=>state.lang==='th'?th:en;
const sellerHeaders=()=>state.sellerSession?{Authorization:'Bearer '+state.sellerSession}:{};
function sellerSessionExpired(msg){state.sellerSession='';state._sellerStoreName='';localStorage.removeItem('collectra_seller_session');toast(msg||L('Please log in again','กรุณาเข้าสู่ระบบอีกครั้ง'));setPage('seller-login')}
async function refreshSellerMe(){try{const r=await api('/api/seller/me',{headers:sellerHeaders()});state._sellerStoreName=r.store.name;if(state.page==='seller-dashboard')render()}catch(e){if(/log in/i.test(e.message))sellerSessionExpired()}}
const NEED=()=>L('Please log in or create an account to continue','กรุณาเข้าสู่ระบบหรือสร้างบัญชีเพื่อดำเนินการต่อ');
function needBuyer(next){if(state.buyerSession)return false;state._afterLogin=next||state.page;toast(NEED());setPage('buyer-login');return true}
function buyerExpire(){state.buyerSession='';state._buyer=null;state.favorites=[];localStorage.removeItem('collectra_buyer_session');if(!/^buyer-/.test(state.page)){state._afterLogin=state.page;toast(L('Please log in again','กรุณาเข้าสู่ระบบอีกครั้ง'));setPage('buyer-login')}}
function buyerStart(r){state.buyerSession=r.session;state._buyer=r.buyer;localStorage.setItem('collectra_buyer_session',r.session);api('/api/favorites',{quiet:true}).then(f=>{state.favorites=f}).catch(()=>{});const n=state._afterLogin||'home';state._afterLogin='';toast(L('Welcome, ','ยินดีต้อนรับ ')+(r.buyer.full_name||'').split(' ')[0]);setPage(n==='buyer-login'||n==='buyer-register'?'home':n)}
function buyerLogout(){fetch('/api/buyer/logout',{method:'POST',headers:{Authorization:'Bearer '+state.buyerSession}}).catch(()=>{});state.buyerSession='';state._buyer=null;state.favorites=[];localStorage.removeItem('collectra_buyer_session');toast(L('Logged out','ออกจากระบบแล้ว'));setPage('home')}
async function refreshBuyer(){if(!state.buyerSession)return;try{const r=await api('/api/buyer/me',{quiet:true});state._buyer=r.buyer}catch(e){state.buyerSession='';state._buyer=null;localStorage.removeItem('collectra_buyer_session')}}
function needVerified(next){const b=state._buyer;if(!state.buyerSession||!b||b.email_verified)return false;toast(L('Please confirm your email first','กรุณายืนยันอีเมลก่อน'));setPage('profile');return true}
function verifyBanner(){const b=state._buyer;if(!state.buyerSession||!b||b.email_verified)return'';return `<div class="notice warn" style="margin-bottom:14px"><strong>${L('Confirm your email to order, pay and review','ยืนยันอีเมลเพื่อสั่งซื้อ ชำระเงิน และรีวิว')}</strong><div class="sub">${L('We sent a link to','เราส่งลิงก์ไปที่')} ${esc(b.email)}. ${L('Open it on this phone or computer. Check your spam folder too.','เปิดลิงก์บนอุปกรณ์นี้ และตรวจสอบโฟลเดอร์สแปมด้วย')}</div><div style="display:flex;gap:8px;margin-top:10px"><input id="bvCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code" placeholder="${L('6-digit code','รหัส 6 หลัก')}" style="flex:1;letter-spacing:4px;font-size:18px"><button class="btn btn-blue" onclick="submitBuyerCode()">${L('Confirm','ยืนยัน')}</button></div><button class="btn btn-outline" style="margin-top:8px" onclick="resendBuyerVerification(this)">${L('Resend email','ส่งอีเมลอีกครั้ง')}</button></div>`}
async function resendBuyerVerification(btn){btn.disabled=true;try{const r=await api('/api/buyer/resend-verification',{method:'POST'});toast(r.message)}catch(e){toast(e.message)}finally{btn.disabled=false}}
function verifyEmailPage(token){setTimeout(()=>confirmEmail(token),0);return shell(`<div class="section-head"><div><h1 class="screen-title">${L('Confirming your email…','กำลังยืนยันอีเมล…')}</h1></div></div><section class="panel"><div id="veMsg"><p class="sub">${L('One moment','รอสักครู่')}</p></div></section>`)}
async function confirmEmail(token){const el=$('#veMsg');if(!el)return;try{const r=await api('/api/verify-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token}),quiet:true});await refreshBuyer();const seller=r.kind==='seller';el.innerHTML=`<div class="notice good"><strong>${L('Email confirmed','ยืนยันอีเมลแล้ว')} ✓</strong><div class="sub">${seller?L('Thank you. Your seller application will now be reviewed. You can log in once it is approved.','ขอบคุณ ใบสมัครผู้ขายของคุณจะถูกตรวจสอบ คุณสามารถเข้าสู่ระบบได้เมื่อได้รับอนุมัติ'):L('Thank you. You can now order, pay and review.','ขอบคุณ ตอนนี้คุณสั่งซื้อ ชำระเงิน และรีวิวได้แล้ว')}</div></div><button class="btn btn-blue" style="margin-top:12px" onclick="setPage('${seller?'sell':(state.buyerSession?'home':'buyer-login')}')">${seller?L('Back to Sell','กลับไปหน้าขาย'):(state.buyerSession?L('Start shopping','เริ่มช้อปปิ้ง'):L('Log in','เข้าสู่ระบบ'))}</button>`}catch(e){el.innerHTML=`<div class="notice bad">${esc(e.message)}</div>`}}
async function sellerResendVerify(){const email=($('#slEmail').value||'').trim(),password=$('#slPassword').value||'';if(!email||!password)return toast(L('Enter your email and password above first','กรอกอีเมลและรหัสผ่านด้านบนก่อน'));try{const r=await api('/api/seller/resend-verification',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});toast(r.message)}catch(e){toast(e.message)}}
async function createVerifyLink(kind,id){try{const r=await api('/api/admin/email-verify-link',{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':state.adminKey},body:JSON.stringify({kind,id}),quiet:true});try{await navigator.clipboard.writeText(r.link)}catch{}prompt('Send this link to the person (valid 48 hours). It is also copied. Only do this if you have confirmed it is really them.',r.link)}catch(e){toast(e.message)}}
function buyerLoginPage(){return shell(`<div class="section-head"><div><h1 class="screen-title">${L('Log in','เข้าสู่ระบบ')}</h1><p>${L('Log in to buy, save favorites and track your orders.','เข้าสู่ระบบเพื่อซื้อสินค้า บันทึกรายการโปรด และติดตามคำสั่งซื้อ')}</p></div></div><section class="panel"><form class="form-grid" onsubmit="buyerLogin(event)"><div class="field"><label>${L('Email','อีเมล')}</label><input name="email" type="email" autocomplete="email" required></div><div class="field"><label>${L('Password','รหัสผ่าน')}</label><input name="password" type="password" autocomplete="current-password" required></div><button id="blBtn" class="btn btn-blue">${L('Log In','เข้าสู่ระบบ')}</button><div id="blMsg"></div></form><p class="sub" style="margin-top:14px"><a href="#buyer-forgot" onclick="setPage('buyer-forgot');return false">${L('Forgot password?','ลืมรหัสผ่าน?')}</a></p><p class="sub" style="margin-top:6px">${L('New here?','ยังไม่มีบัญชี?')} <a href="#buyer-register" onclick="setPage('buyer-register');return false">${L('Create an account','สร้างบัญชี')}</a></p></section>`)}
async function buyerLogin(e){e.preventDefault();const f=e.target,b=$('#blBtn');b.disabled=true;try{const r=await api('/api/buyer/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:f.email.value,password:f.password.value}),quiet:true});buyerStart(r)}catch(err){$('#blMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(err.message)}</div>`}finally{b.disabled=false}}
function buyerRegisterPage(){return shell(`<div class="section-head"><div><h1 class="screen-title">${L('Create an account','สร้างบัญชี')}</h1><p>${L('One account for buying, favorites, orders and unboxing videos. No ID needed.','บัญชีเดียวสำหรับซื้อสินค้า รายการโปรด คำสั่งซื้อ และวิดีโอแกะกล่อง ไม่ต้องใช้บัตรประชาชน')}</p></div></div><section class="panel"><form class="form-grid" onsubmit="buyerRegister(event)"><div class="field"><label>${L('Full name','ชื่อ-นามสกุล')}</label><input name="full_name" autocomplete="name" required></div><div class="field"><label>${L('Email','อีเมล')}</label><input name="email" type="email" autocomplete="email" required></div><div class="field"><label>${L('Phone (optional)','เบอร์โทร (ไม่บังคับ)')}</label><input name="phone" type="tel" inputmode="tel" autocomplete="tel"></div><div class="grid-2"><div class="field"><label>${L('Password (8+ characters)','รหัสผ่าน (อย่างน้อย 8 ตัว)')}</label><input name="password" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label>${L('Confirm password','ยืนยันรหัสผ่าน')}</label><input name="password2" type="password" minlength="8" autocomplete="new-password" required></div></div><button id="brBtn" class="btn btn-blue">${L('Create Account','สร้างบัญชี')}</button><div id="brMsg"></div></form><p class="sub" style="margin-top:14px">${L('Already have an account?','มีบัญชีอยู่แล้ว?')} <a href="#buyer-login" onclick="setPage('buyer-login');return false">${L('Log in','เข้าสู่ระบบ')}</a></p></section>`)}
async function buyerRegister(e){e.preventDefault();const f=e.target;if(f.password.value!==f.password2.value)return $('#brMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${L('Passwords do not match','รหัสผ่านไม่ตรงกัน')}</div>`;const b=$('#brBtn');b.disabled=true;try{const r=await api('/api/buyer/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:f.email.value,password:f.password.value,full_name:f.full_name.value,phone:f.phone.value}),quiet:true});state._afterLogin='profile';buyerStart(r);setTimeout(()=>toast(L('Check your email to confirm your account','ตรวจสอบอีเมลเพื่อยืนยันบัญชีของคุณ')),900)}catch(err){$('#brMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(err.message)}</div>`}finally{b.disabled=false}}
function buyerForgotPage(){return shell(`<button class="ghost" onclick="setPage('buyer-login')">← ${L('Back to login','กลับไปหน้าเข้าสู่ระบบ')}</button><div class="section-head"><div><h1 class="screen-title">${L('Forgot password','ลืมรหัสผ่าน')}</h1><p>${L('Enter your email and we will send you a link to choose a new password.','กรอกอีเมล เราจะส่งลิงก์สำหรับตั้งรหัสผ่านใหม่ให้')}</p></div></div><section class="panel"><form class="form-grid" onsubmit="buyerForgot(event)"><div class="field"><label>${L('Email','อีเมล')}</label><input name="email" type="email" autocomplete="email" required></div><button id="bfBtn" class="btn btn-blue">${L('Send reset link','ส่งลิงก์รีเซ็ต')}</button><div id="bfMsg"></div></form></section>`)}
async function buyerForgot(e){e.preventDefault();const b=$('#bfBtn');b.disabled=true;try{const r=await api('/api/buyer/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e.target.email.value}),quiet:true});$('#bfMsg').innerHTML=`<div class="notice good" style="margin-top:10px">${esc(r.message)}</div>`}catch(err){$('#bfMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(err.message)}</div>`}finally{b.disabled=false}}
function buyerResetPage(token){return shell(`<div class="section-head"><div><h1 class="screen-title">${L('Choose a new password','ตั้งรหัสผ่านใหม่')}</h1></div></div><section class="panel"><form class="form-grid" onsubmit="buyerReset(event,'${esc(token)}')"><div class="field"><label>${L('New password','รหัสผ่านใหม่')}</label><input name="password" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label>${L('Confirm new password','ยืนยันรหัสผ่านใหม่')}</label><input name="password2" type="password" minlength="8" autocomplete="new-password" required></div><button id="brsBtn" class="btn btn-blue">${L('Change password','เปลี่ยนรหัสผ่าน')}</button><div id="brsMsg"></div></form></section>`)}
async function buyerReset(e,token){e.preventDefault();const f=e.target;if(f.password.value!==f.password2.value)return $('#brsMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${L('Passwords do not match','รหัสผ่านไม่ตรงกัน')}</div>`;const b=$('#brsBtn');b.disabled=true;try{await api('/api/buyer/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,password:f.password.value}),quiet:true});toast(L('Password changed. Please log in.','เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบ'));setPage('buyer-login')}catch(err){$('#brsMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(err.message)}</div>`}finally{b.disabled=false}}
function sell(){const intro=L('Sell on Collectra with your own account. Every seller is checked with a national ID before they can list or ship.','ขายบน Collectra ด้วยบัญชีของคุณเอง ผู้ขายทุกคนต้องผ่านการตรวจสอบบัตรประชาชนก่อนลงขายหรือจัดส่ง');if(state.sellerSession)return shell(`<div class="section-head"><div><h1 class="screen-title">${t('sell_title')}</h1><p>${L("You're logged in as a seller on this device.",'คุณเข้าสู่ระบบเป็นผู้ขายบนอุปกรณ์นี้')}</p></div></div><section class="panel"><h2>${L('Continue to your store','ไปที่ร้านของคุณ')}</h2><button class="btn btn-primary" onclick="setPage('seller-dashboard')">${L('Open Seller Dashboard','เปิดแดชบอร์ดผู้ขาย')}</button></section>`);return shell(`<div class="section-head"><div><h1 class="screen-title">${t('sell_title')}</h1><p>${intro}</p></div></div><div class="grid-2"><section class="panel"><h2>${L('Already approved?','ได้รับอนุมัติแล้ว?')}</h2><p>${L('Log in with your email and password to manage listings and packing videos.','เข้าสู่ระบบด้วยอีเมลและรหัสผ่านเพื่อจัดการสินค้าและวิดีโอแพ็ค')}</p><button class="btn btn-primary" onclick="setPage('seller-login')">${L('Log In as Seller','เข้าสู่ระบบผู้ขาย')}</button></section><section class="panel yellow"><h2>${L('Become a Seller','สมัครเป็นผู้ขาย')}</h2><p>${L('Create an account with your email, a password and your national ID card.','สร้างบัญชีด้วยอีเมล รหัสผ่าน และบัตรประชาชน')}</p><button class="btn btn-blue" onclick="setPage('seller-register')">${L('Create Seller Account','สร้างบัญชีผู้ขาย')}</button></section></div>`)}
function capField(field,label,facing){return `<div class="field"><label>${label}</label><div class="cap"><div id="prev-${field}"></div><div class="cap-actions"><button type="button" class="btn btn-outline" onclick="openCapture('${field}','${facing}')">${L('Open camera','เปิดกล้อง')}</button><label class="cap-file">${L('or choose a file','หรือเลือกไฟล์')}<input type="file" accept="image/*" hidden onchange="pickCapFile('${field}',this)"></label></div></div></div>`}
async function openCapture(field,facing){closeCapture();const box=$('#prev-'+field);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:facing,width:{ideal:1280}},audio:false});state._capStream=stream;box.innerHTML=`<video id="capVideo" class="${facing==='user'?'mirror':''}" autoplay playsinline muted></video><div class="cap-actions"><button type="button" class="btn btn-primary" onclick="snapCapture('${field}')">${L('Take photo','ถ่ายรูป')}</button><button type="button" class="btn btn-outline" onclick="closeCapture('${field}')">${L('Cancel','ยกเลิก')}</button></div>`;const v=$('#capVideo');v.srcObject=stream;await v.play().catch(()=>{})}catch(e){box.innerHTML=`<div class="notice warn">${L('Could not open the camera. Allow camera access in your browser, or choose a file instead.','เปิดกล้องไม่ได้ กรุณาอนุญาตการเข้าถึงกล้อง หรือเลือกไฟล์แทน')}</div>`}}
function closeCapture(field){if(state._capStream){state._capStream.getTracks().forEach(t=>t.stop());state._capStream=null}if(field)showCapPreview(field)}
function showCapPreview(field){const box=$('#prev-'+field);if(!box)return;const r=(state.reg||{})[field];box.innerHTML=r?`<img src="${r.url}" class="cap-img" alt=""><div class="sub">${r.source==='camera'?L('Taken with the camera ✓','ถ่ายด้วยกล้องแล้ว ✓'):L('Chosen from files (the admin will see this)','เลือกจากไฟล์ (ผู้ดูแลจะเห็นข้อมูลนี้)')}</div>`:''}
function snapCapture(field){const v=$('#capVideo');if(!v||!v.videoWidth)return toast(L('Camera is still starting, try again','กล้องกำลังเริ่มทำงาน ลองอีกครั้ง'));const sc=Math.min(1,1600/Math.max(v.videoWidth,v.videoHeight));const c=document.createElement('canvas');c.width=Math.round(v.videoWidth*sc);c.height=Math.round(v.videoHeight*sc);c.getContext('2d').drawImage(v,0,0,c.width,c.height);c.toBlob(b=>{const old=state.reg[field];if(old)URL.revokeObjectURL(old.url);state.reg[field]={blob:b,source:'camera',url:URL.createObjectURL(b)};closeCapture(field)},'image/jpeg',.9)}
function pickCapFile(field,input){const f=input.files[0];if(!f)return;closeCapture();const old=state.reg[field];if(old)URL.revokeObjectURL(old.url);state.reg[field]={blob:f,source:'upload',url:URL.createObjectURL(f)};showCapPreview(field)}
async function loadChallenge(fresh){try{state.reg=state.reg||{};if(fresh&&state.reg.id_selfie){URL.revokeObjectURL(state.reg.id_selfie.url);delete state.reg.id_selfie;showCapPreview('id_selfie')}state.reg.chal=await api('/api/seller/challenge');const el=$('#challengeCode');if(el)el.textContent=state.reg.chal.code}catch(e){const el=$('#challengeCode');if(el)el.textContent='?'}}
function sellerRegisterPage(){state.reg={};setTimeout(loadChallenge,0);return shell(`<button class="ghost" onclick="setPage('sell')">← ${t('nav_sell')}</button><div class="section-head"><div><h1 class="screen-title">${L('Create Seller Account','สร้างบัญชีผู้ขาย')}</h1><p>${L('We check every seller against their national ID so buyers can trust the shops. Only Collectra admins can see your ID, and it is never shown to buyers.','เราตรวจสอบผู้ขายทุกคนกับบัตรประชาชนเพื่อให้ผู้ซื้อมั่นใจ เฉพาะผู้ดูแล Collectra เท่านั้นที่เห็นบัตรของคุณ และไม่แสดงให้ผู้ซื้อ')}</p></div></div><section class="panel"><form id="sellerRegForm" class="form-grid" onsubmit="sellerRegister(event)"><div class="field"><label>${L('Email','อีเมล')}</label><input name="email" type="email" autocomplete="email" required></div><div class="grid-2"><div class="field"><label>${L('Password (8+ characters)','รหัสผ่าน (อย่างน้อย 8 ตัว)')}</label><input name="password" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label>${L('Confirm password','ยืนยันรหัสผ่าน')}</label><input name="password2" type="password" minlength="8" autocomplete="new-password" required></div></div><div class="grid-2"><div class="field"><label>${L('Full name (as on your ID)','ชื่อ-นามสกุล (ตามบัตรประชาชน)')}</label><input name="full_name" required></div><div class="field"><label>${L('Shop name','ชื่อร้าน')}</label><input name="shop_name" required></div></div><div class="grid-2"><div class="field"><label>${L('Phone','เบอร์โทร')}</label><input name="phone" type="tel" inputmode="tel"></div><div class="field"><label>${L('National ID number (13 digits)','เลขบัตรประชาชน (13 หลัก)')}</label><input name="id_number" inputmode="numeric" maxlength="17" placeholder="1-2345-67890-12-3" required></div></div>${capField('id_front',L('1. Photo of the front of your national ID card','1. รูปด้านหน้าบัตรประชาชน'),'environment')}<div class="notice warn challenge-box"><strong>${L('2. Write this code on a piece of paper','2. เขียนรหัสนี้ลงบนกระดาษ')}</strong><div class="challenge-code" id="challengeCode">····</div><div class="sub">${L('Then take a selfie where your face, your ID card and the paper with the code are all clearly visible. The code changes every time, so an old photo cannot be reused.','จากนั้นถ่ายเซลฟี่ให้เห็นใบหน้า บัตรประชาชน และกระดาษที่มีรหัสชัดเจน รหัสเปลี่ยนทุกครั้ง จึงใช้รูปเก่าไม่ได้')}</div><a href="#" class="sub" onclick="loadChallenge(true);return false">${L('Get a new code','ขอรหัสใหม่')}</a></div>${capField('id_selfie',L('3. Selfie holding your ID card and the code','3. เซลฟี่ถือบัตรและกระดาษรหัส'),'user')}<button id="regBtn" class="btn btn-blue">${L('Submit for Approval','ส่งเพื่อขออนุมัติ')}</button><div id="sellerRegMsg"></div></form></section>`)}
async function sellerRegister(e){e.preventDefault();const f=e.target,fd=new FormData(f),R=state.reg||{},msg=$('#sellerRegMsg'),bad=m=>msg.innerHTML=`<div class="notice bad" style="margin-top:10px">${m}</div>`;if(fd.get('password')!==fd.get('password2'))return bad(L('Passwords do not match','รหัสผ่านไม่ตรงกัน'));if(!R.id_front)return bad(L('Please add the photo of your ID card','กรุณาเพิ่มรูปบัตรประชาชน'));if(!R.id_selfie)return bad(L('Please take the selfie holding your ID and the code','กรุณาถ่ายเซลฟี่ถือบัตรและรหัส'));if(!R.chal)return bad(L('The selfie code did not load. Reload the page.','รหัสเซลฟี่ไม่แสดง กรุณารีโหลดหน้า'));fd.delete('password2');fd.append('id_front',R.id_front.blob,'id-front.jpg');fd.append('id_selfie',R.id_selfie.blob,'selfie.jpg');fd.append('id_source',R.id_front.source);fd.append('selfie_source',R.id_selfie.source);fd.append('challenge',R.chal.code);fd.append('challenge_ts',R.chal.ts);fd.append('challenge_sig',R.chal.sig);const b=$('#regBtn');b.disabled=true;b.textContent=L('Uploading…','กำลังอัปโหลด…');try{const r=await api('/api/seller/register',{method:'POST',body:fd});f.reset();state.reg={};['id_front','id_selfie'].forEach(showCapPreview);msg.innerHTML=`<div class="notice good" style="margin-top:10px">${esc(r.message)}</div>`}catch(err){bad(esc(err.message))}finally{b.disabled=false;b.textContent=L('Submit for Approval','ส่งเพื่อขออนุมัติ')}}
function sellerForgotPage(){return shell(`<button class="ghost" onclick="setPage('seller-login')">← ${L('Back to login','กลับไปหน้าเข้าสู่ระบบ')}</button><div class="section-head"><div><h1 class="screen-title">${L('Forgot password','ลืมรหัสผ่าน')}</h1><p>${L('Enter the email you registered with. We will send you a link to choose a new password.','กรอกอีเมลที่ใช้สมัคร เราจะส่งลิงก์สำหรับตั้งรหัสผ่านใหม่ให้')}</p></div></div><section class="panel"><form class="form-grid" onsubmit="sellerForgot(event)"><div class="field"><label>${L('Email','อีเมล')}</label><input name="email" type="email" autocomplete="email" required></div><button id="fgBtn" class="btn btn-blue">${L('Send reset link','ส่งลิงก์รีเซ็ต')}</button><div id="fgMsg"></div></form></section>`)}
async function sellerForgot(e){e.preventDefault();const b=$('#fgBtn');b.disabled=true;try{const r=await api('/api/seller/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e.target.email.value})});$('#fgMsg').innerHTML=`<div class="notice good" style="margin-top:10px">${esc(r.message)}</div>`}catch(err){$('#fgMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(err.message)}</div>`}finally{b.disabled=false}}
function sellerResetPage(token){return shell(`<div class="section-head"><div><h1 class="screen-title">${L('Choose a new password','ตั้งรหัสผ่านใหม่')}</h1><p>${L('Pick a password with at least 8 characters.','รหัสผ่านอย่างน้อย 8 ตัวอักษร')}</p></div></div><section class="panel"><form class="form-grid" onsubmit="sellerReset(event,'${esc(token)}')"><div class="field"><label>${L('New password','รหัสผ่านใหม่')}</label><input name="password" type="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label>${L('Confirm new password','ยืนยันรหัสผ่านใหม่')}</label><input name="password2" type="password" minlength="8" autocomplete="new-password" required></div><button id="rsBtn" class="btn btn-blue">${L('Change password','เปลี่ยนรหัสผ่าน')}</button><div id="rsMsg"></div></form></section>`)}
async function sellerReset(e,token){e.preventDefault();const f=e.target;if(f.password.value!==f.password2.value)return $('#rsMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${L('Passwords do not match','รหัสผ่านไม่ตรงกัน')}</div>`;const b=$('#rsBtn');b.disabled=true;try{await api('/api/seller/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,password:f.password.value})});toast(L('Password changed. Please log in.','เปลี่ยนรหัสผ่านแล้ว กรุณาเข้าสู่ระบบ'));setPage('seller-login')}catch(err){$('#rsMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(err.message)}</div>`}finally{b.disabled=false}}
function sellerLoginPage(){return shell(`<button class="ghost" onclick="setPage('sell')">← ${t('nav_sell')}</button><div class="section-head"><div><h1 class="screen-title">${L('Seller Login','เข้าสู่ระบบผู้ขาย')}</h1><p>${L('Use the email and password you registered with.','ใช้อีเมลและรหัสผ่านที่คุณสมัครไว้')}</p></div></div><section class="panel"><form class="form-grid" onsubmit="event.preventDefault();sellerLogin()"><div class="field"><label>${L('Email','อีเมล')}</label><input id="slEmail" type="email" autocomplete="email" required></div><div class="field"><label>${L('Password','รหัสผ่าน')}</label><input id="slPassword" type="password" autocomplete="current-password" required></div><button id="slBtn" class="btn btn-blue">${L('Log In','เข้าสู่ระบบ')}</button><div id="sellerLoginMsg"></div></form><p class="sub" style="margin-top:14px"><a href="#seller-forgot" onclick="setPage('seller-forgot');return false">${L('Forgot password?','ลืมรหัสผ่าน?')}</a></p><div style="display:flex;gap:8px;margin-top:14px"><input id="slCode" inputmode="numeric" maxlength="6" placeholder="${L('6-digit email code','รหัสอีเมล 6 หลัก')}" style="flex:1;letter-spacing:4px"><button type="button" class="btn btn-outline" onclick="submitSellerCode()">${L('Confirm email','ยืนยันอีเมล')}</button></div><p class="sub" style="margin-top:6px"><a href="#" onclick="sellerResendVerify();return false">${L('Did not get the confirmation email? Resend it','ไม่ได้รับอีเมลยืนยัน? ส่งอีกครั้ง')}</a></p><p class="sub" style="margin-top:6px">${L('No account yet?','ยังไม่มีบัญชี?')} <a href="#seller-register" onclick="setPage('seller-register');return false">${L('Create a seller account','สร้างบัญชีผู้ขาย')}</a></p></section>`)}
async function sellerLogin(){const email=($('#slEmail').value||'').trim(),password=$('#slPassword').value||'';if(!email||!password)return toast(L('Enter your email and password','กรอกอีเมลและรหัสผ่าน'));const b=$('#slBtn');b.disabled=true;try{const r=await api('/api/seller/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});state.sellerSession=r.session;state._sellerStoreName=r.store.name;localStorage.setItem('collectra_seller_session',r.session);toast(L('Logged in as ','เข้าสู่ระบบเป็น ')+r.store.name);setPage('seller-dashboard')}catch(e){$('#sellerLoginMsg').innerHTML=`<div class="notice bad" style="margin-top:10px">${esc(e.message)}</div>`}finally{b.disabled=false}}
function sellerLogout(){fetch('/api/seller/logout',{method:'POST',headers:sellerHeaders()}).catch(()=>{});state.sellerSession='';state._sellerStoreName='';localStorage.removeItem('collectra_seller_session');toast(L('Logged out','ออกจากระบบแล้ว'));setPage('sell')}
function sellerDashboardPage(){if(!state.sellerSession){setPage('seller-login');return''}if(!state._sellerStoreName)refreshSellerMe();return shell(`<button class="ghost" onclick="sellerLogout()">Log Out</button><div class="section-head"><div><h1 class="screen-title">${esc(state._sellerStoreName||'Seller Dashboard')}</h1><p>Manage your store from here.</p></div></div><div class="grid-2"><section class="panel"><h2>Listings</h2><p>Upload new stock with real photos and quantities.</p><button class="btn btn-blue" onclick="setPage('seller-tools')">Upload Listing</button></section><section class="panel yellow"><h2>Packing Videos</h2><p>Record the required packing video for orders containing your items.</p><button class="btn btn-primary" onclick="setPage('seller-orders')">Open Seller Orders</button></section></div>`)}
function sellerTools(){const back=state.sellerSession?'seller-dashboard':'sell';return shell(`<button class="ghost" onclick="setPage('${back}')">← Back</button><div class="section-head"><div><h1 class="screen-title">Upload Listing</h1><p>Upload real stock to your approved store.</p></div></div><section class="panel"><form id="productForm" class="form-grid" onsubmit="uploadProduct(event)"><div class="grid-2"><div class="field"><label>Product title</label><input name="title" required></div><div class="field"><label>Category</label><select name="category"><option>K-pop</option><option>T-pop</option><option>Other</option></select></div></div><div class="grid-2"><div class="field"><label>Price (THB)</label><input name="price" type="number" min="0" step="0.01" required></div><div class="field"><label>Stock quantity</label><input name="stock" type="number" min="1" value="1" required></div></div><div class="field"><label>Condition</label><input name="condition" value="Like New"></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Listing photo</label><input name="image" type="file" accept="image/*" capture="environment" required></div><button class="btn btn-blue">Upload Listing</button><div id="uploadMsg"></div></form></section>`)}
async function uploadProduct(e){e.preventDefault();const fd=new FormData(e.target);const b=$('button',e.target);b.disabled=true;b.textContent='Uploading…';try{await api('/api/products',{method:'POST',body:fd,headers:sellerHeaders()});$('#uploadMsg').innerHTML='<div class="notice good">Listing is live.</div>';state.products=await api('/api/products');e.target.reset()}catch(err){if(/log in/i.test(err.message))return sellerSessionExpired(err.message);$('#uploadMsg').innerHTML=`<div class="notice bad">${esc(err.message)}</div>`}finally{b.disabled=false;b.textContent='Upload Listing'}}

function support(){return shell(`<div class="section-head"><div><h1 class="screen-title">Collectra Support</h1><p>Start with the AI assistant, or ask for a real human admin.</p></div></div><section class="panel chat"><div class="quick-actions"><button onclick="sendQuick('How does card verification work?')">Verify a card</button><button onclick="sendQuick('How do I track my order?')">Track order</button><button onclick="sendQuick('How do I become a seller?')">Seller help</button><button onclick="requestHuman('I would like to speak to a human admin.')">Request Human Admin</button></div><div class="messages" id="messages"><div class="msg ai">Hi! I’m the Collectra AI assistant ✨ How can I help?</div></div><div class="chat-input"><input id="chatText" placeholder="Type your message…" onkeydown="if(event.key==='Enter')sendChat()"><button class="btn btn-blue" onclick="sendChat()">→</button></div></section>`)}
function addMsg(text,who){const el=$('#messages');if(!el)return;el.insertAdjacentHTML('beforeend',`<div class="msg ${who}">${esc(text)}</div>`);el.scrollTop=el.scrollHeight}
function sendQuick(t){$('#chatText').value=t;sendChat()}
async function sendChat(){const i=$('#chatText');const m=i.value.trim();if(!m)return;i.value='';addMsg(m,'user');addMsg('Thinking…','ai');try{const r=await api('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:m})});$('#messages .msg.ai:last-child').textContent=r.reply}catch{$('#messages .msg.ai:last-child').textContent='Could not reach support.'}}
async function requestHuman(message){const email=prompt('Email for the admin reply (optional):')||'';await api('/api/support-ticket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,message})});toast('Human admin request sent')}

function cart(){const rows=state.cart.map(ci=>{const p=state.products.find(x=>x.id===ci.product_id);if(!p)return'';return `<div class="cart-row"><img src="${p.image_url}"><div class="grow"><strong>${esc(p.title)}</strong><div>${money(p.price)} × ${ci.qty}</div></div><button class="ghost" onclick="removeCart(${p.id})">Remove</button></div>`}).join('');const total=state.cart.reduce((sum,ci)=>{const p=state.products.find(x=>x.id===ci.product_id);return sum+(p?p.price*ci.qty:0)},0);return shell(`<div class="section-head"><div><h1 class="screen-title">Cart</h1><p>Your order reduces stock when checkout is created.</p></div></div><section class="panel">${rows||'<div class="empty">Cart is empty.</div>'}${state.cart.length?`<h2>Total ${money(total)}</h2><button class="btn btn-primary btn-full" onclick="setPage('checkout')">Checkout</button>`:''}</section>`)}
function removeCart(id){state.cart=state.cart.filter(x=>x.product_id!==id);saveCart();render()}
async function checkout(){if(needBuyer('cart')||needVerified())return;const addrs=await api('/api/addresses');state._addresses=addrs;state._useNewAddress=!addrs.length;state.page='checkout-ready';render()}
const ADDRESS_FIELDS=['label','name','phone','line1','district','city','province','postal'];
function addressFormFields(){return ADDRESS_FIELDS.map(k=>`<div class="field"><label>${k==='line1'?'Address line':k[0].toUpperCase()+k.slice(1)}</label><input name="${k}" ${['label','name','phone','line1','city','province','postal'].includes(k)?'required':''}></div>`).join('')}
function checkoutReady(){const addrs=state._addresses||[];const useNew=state._useNewAddress;return shell(`<div class="section-head"><div><h1 class="screen-title">Checkout</h1><p>Use a saved address or add a new one — no need to visit Profile first.</p></div></div><section class="panel">${addrs.length?`<div class="field"><label>Saved address</label><select id="checkoutAddress" onchange="state._useNewAddress=false;render()" ${useNew?'disabled':''}>${addrs.map(a=>`<option value="${a.id}">${esc(a.label)} — ${esc(a.line1)}, ${esc(a.city)}</option>`).join('')}</select></div>`:'<div class="notice warn">No saved address yet — add one below.</div>'}${addrs.length?`<button type="button" class="btn btn-outline btn-full" style="margin:12px 0" onclick="state._useNewAddress=${useNew?'false':'true'};render()">${useNew?'← Use a saved address instead':'+ Use a different address'}</button>`:''}<form id="newAddressForm" class="form-grid" style="${(useNew||!addrs.length)?'':'display:none'}">${addressFormFields()}</form><button class="btn btn-primary btn-full" style="margin-top:14px" onclick="createOrder()">Create Order</button></section>`)}
async function createOrder(){try{let address_id;const addrs=state._addresses||[];if(state._useNewAddress||!addrs.length){const form=$('#newAddressForm');const d=Object.fromEntries(new FormData(form));const required=['label','name','phone','line1','city','province','postal'];const missing=required.filter(k=>!d[k]);if(missing.length)return toast('Fill in: '+missing.join(', '));d.is_default=true;const ra=await api('/api/addresses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});address_id=ra.id}else{address_id=Number($('#checkoutAddress').value)}const r=await api('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({address_id,items:state.cart})});state.cart=[];saveCart();toast('Order created');state.lastOrder=r.order_id;setPage('orders')}catch(e){toast(e.message)}}

function profile(){const b=state._buyer;const acct=b?`<section class="panel blue" style="margin-bottom:16px"><h2>${esc(b.full_name)}</h2><p>${esc(b.email)}</p><button class="btn btn-white" onclick="buyerLogout()">${L('Log out','ออกจากระบบ')}</button></section>`:`<section class="panel blue" style="margin-bottom:16px"><h2>${L('Welcome to Collectra','ยินดีต้อนรับสู่ Collectra')}</h2><p>${L('Log in or create an account to buy, save favorites and track orders.','เข้าสู่ระบบหรือสร้างบัญชีเพื่อซื้อสินค้า บันทึกรายการโปรด และติดตามคำสั่งซื้อ')}</p><div class="toolbar"><button class="btn btn-white" onclick="setPage('buyer-login')">${L('Log In','เข้าสู่ระบบ')}</button><button class="btn btn-primary" onclick="setPage('buyer-register')">${L('Create Account','สร้างบัญชี')}</button></div></section>`;return shell(`<div class="section-head"><div><h1 class="screen-title">${t('profile_title')}</h1><p>${L('Your Collectra tools and saved information.','เครื่องมือและข้อมูลของคุณบน Collectra')}</p></div></div>${verifyBanner()}${acct}<div class="feature-grid">${profileTile('📦',L('Orders','คำสั่งซื้อ'),L('Tracking, payment slips and evidence','การติดตาม สลิป และหลักฐาน'),'orders')}${profileTile('⌂',L('Addresses','ที่อยู่'),L('Save delivery addresses','บันทึกที่อยู่จัดส่ง'),'addresses')}${profileTile('💬',L('Support','ช่วยเหลือ'),L('AI chat or human admin','แชท AI หรือผู้ดูแล'),'support')}${profileTile('🏪',L('Sell on Collectra','ขายบน Collectra'),L('Seller account and dashboard','บัญชีและแดชบอร์ดผู้ขาย'),'sell')}</div><section class="panel yellow" style="margin-top:18px"><h2>${L('Install on your phone','ติดตั้งบนมือถือ')}</h2><p>${L('In Safari or Chrome, use Add to Home Screen. The site is designed to feel like a mobile app.','ใน Safari หรือ Chrome เลือก เพิ่มไปยังหน้าจอโฮม เว็บไซต์ออกแบบให้ใช้งานเหมือนแอปมือถือ')}</p></section>`)}
function profileTile(i,t,d,p){return `<button class="feature-card" style="text-align:left;border:1px solid #d6e6ff" onclick="setPage('${p}')"><div class="feature-icon">${i}</div><h3>${t}</h3><p>${d}</p></button>`}
async function addresses(){if(needBuyer('profile'))return;state._addresses=await api('/api/addresses');state.page='addresses-ready';render()}
function addressesReady(){return shell(`<div class="section-head"><div><h1 class="screen-title">Saved Addresses</h1><p>Add an address once and reuse it at checkout — or add a new one right at checkout too.</p></div></div><div class="grid-2"><section class="panel"><h2>Your addresses</h2>${(state._addresses||[]).map(a=>`<div class="address-row"><div><strong>${esc(a.label)}</strong><div>${esc(a.name)} · ${esc(a.phone)}</div><div class="sub">${esc(a.line1)}, ${esc(a.city)}, ${esc(a.province)} ${esc(a.postal)}</div></div></div>`).join('')||'<div class="empty">No saved address yet.</div>'}</section><section class="panel yellow"><h2>Add Address</h2><form id="addressForm" class="form-grid" onsubmit="saveAddress(event)">${addressFormFields()}<button class="btn btn-blue">Save Address</button></form></section></div>`)}
async function saveAddress(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.is_default=true;await api('/api/addresses',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});toast('Address saved');addresses()}
async function orders(){if(needBuyer('profile'))return;state._orders=await api('/api/orders');state.page='orders-ready';render()}
function aiEvidenceBadge(status,confidence,summary,aiJson){if(!status)return'';const cls=status==='Verified'?'good':status==='Suspicious'?'bad':'warn';let authLine='';try{const j=aiJson?JSON.parse(aiJson):null;if(j&&j.authenticity_status){const acls=j.authenticity_status==='Likely Authentic'?'good':j.authenticity_status==='Suspicious'?'bad':'warn';authLine=`<div class="notice ${acls}" style="margin-top:4px"><strong>Card authenticity (from video): ${esc(j.authenticity_status)}${j.authenticity_confidence?` (${j.authenticity_confidence}%)`:''}</strong></div>`}}catch(e){}return `<div class="notice ${cls}" style="margin-top:6px"><strong>AI check: ${esc(status)}${confidence?` (${confidence}%)`:''}</strong>${summary?`<div class="sub">${esc(summary)}</div>`:''}</div>${authLine}`}
function ordersReady(){return shell(`${verifyBanner()}<div class="section-head"><div><h1 class="screen-title">Orders</h1><p>Payment slips plus guided, uninterrupted packing and unboxing video evidence.</p></div></div>${(state._orders||[]).map(o=>`<section class="panel" style="margin-bottom:14px"><div class="store-title"><div><h2>Order #${o.id}</h2><div class="sub">${new Date(o.created_at).toLocaleString()}</div></div><span class="badge">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-row"><div class="grow">${esc(i.title)}</div><strong>${i.qty} × ${money(i.unit_price)}</strong></div>`).join('')}<h3>Total ${money(o.total)}</h3><div class="notice ${o.payment_status==='slip_uploaded'?'good':'warn'}">Payment: ${esc(o.payment_status)}</div>${o.slip_url?aiEvidenceBadge(o.slip_ai_status,o.slip_ai_confidence,o.slip_ai_summary,o.slip_ai_json):''}<div class="evidence-status-grid"><div class="evidence-status ${o.packing_video_url?'done':''}"><strong>Seller Packing</strong><span>${o.packing_video_url?'✓ Video uploaded':'Video required'}</span>${aiEvidenceBadge(o.packing_ai_status,o.packing_ai_confidence,o.packing_ai_summary,o.packing_ai_json)}</div><div class="evidence-status ${o.unboxing_video_url?'done':''}"><strong>Buyer Unboxing</strong><span>${o.unboxing_video_url?'✓ Video uploaded':'Video required'}</span>${aiEvidenceBadge(o.unboxing_ai_status,o.unboxing_ai_confidence,o.unboxing_ai_summary,o.unboxing_ai_json)}</div></div>${o.evidence_match_status?`<div class="notice ${o.evidence_match_status==='Verified'?'good':o.evidence_match_status==='Mismatch'?'bad':'warn'}"><strong>Packing ↔ Unboxing cross-check: ${esc(o.evidence_match_status)}</strong></div>`:''}<div class="toolbar"><label class="btn btn-outline">Upload Slip<input hidden type="file" accept="image/*" capture="environment" onchange="uploadOrderFile(${o.id},'slip',this.files[0])"></label><button class="btn btn-primary" onclick="openEvidenceRecorder(${o.id},'unboxing','orders')">Record Unboxing Video</button></div><div class="sub" style="margin-top:6px">Payment slip: upload a photo or screenshot. Unboxing video: must be recorded live in the app.</div>${o.tracking_number?`<div>Tracking: <strong>${esc(o.tracking_number)}</strong></div>`:''}</section>`).join('')||'<div class="empty">No orders yet.</div>'}`)}
async function uploadOrderFile(order_id,kind,file){if(!file||needBuyer('orders')||needVerified())return;const fd=new FormData();fd.append('order_id',order_id);fd.append('slip',file);const r=await api('/api/payment-slip',{method:'POST',body:fd});toast(r.ai?.status?`Payment slip uploaded — AI: ${r.ai.status}`:'Payment slip uploaded');orders()}
function sellerOrdersPage(){const back=state.sellerSession?'seller-dashboard':'sell';return shell(`<button class="ghost" onclick="setPage('${back}')">← Back</button><div class="section-head"><div><h1 class="screen-title">${t('seller_orders_title')}</h1><p>Record the required packing video for orders that include your store's items.</p></div></div><div id="sellerOrdersList"><p class="sub">Loading orders…</p></div>`)}
async function sellerOrders(){if(!state.sellerSession){setPage('seller-login');return}if(state.page!=='seller-orders'){state.page='seller-orders';render()}try{const r=await api('/api/seller-orders',{headers:sellerHeaders()});state._sellerStoreName=r.store_name;state._sellerOrders=r.orders;renderSellerOrdersList()}catch(e){if(/log in/i.test(e.message))return sellerSessionExpired(e.message);toast(e.message);const el=$('#sellerOrdersList');if(el)el.innerHTML=''}}
async function saveTracking(id){const v=($('#trk-'+id).value||'').trim();if(!v)return toast(L('Enter the tracking number','กรอกเลขพัสดุ'));try{await api('/api/seller/order-tracking',{method:'POST',headers:{...sellerHeaders(),'Content-Type':'application/json'},body:JSON.stringify({order_id:id,tracking_number:v})});toast(L('Marked as shipped','ทำเครื่องหมายจัดส่งแล้ว'));sellerOrders()}catch(e){if(/log in/i.test(e.message))return sellerSessionExpired(e.message);toast(e.message)}}
function renderSellerOrdersList(){const el=$('#sellerOrdersList');if(!el)return;const orders=state._sellerOrders||[];el.innerHTML=`<div class="section-head"><div><h2>${esc(state._sellerStoreName||'')}</h2><p>${orders.length} order(s) containing your items</p></div></div>${orders.map(o=>`<section class="panel" style="margin-bottom:14px"><div class="store-title"><div><h2>Order #${o.id}</h2><div class="sub">${new Date(o.created_at).toLocaleString()}</div></div><span class="badge">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-row"><div class="grow">${esc(i.title)}</div><strong>${i.qty} × ${money(i.unit_price)}</strong></div>`).join('')}<div class="evidence-status-grid"><div class="evidence-status ${o.packing_video_url?'done':''}"><strong>Your Packing Video</strong><span>${o.packing_video_url?'✓ Video uploaded':'Video required'}</span>${aiEvidenceBadge(o.packing_ai_status,o.packing_ai_confidence,o.packing_ai_summary,o.packing_ai_json)}</div><div class="evidence-status ${o.unboxing_video_url?'done':''}"><strong>Buyer Unboxing</strong><span>${o.unboxing_video_url?'✓ Video uploaded':'Not yet received'}</span>${aiEvidenceBadge(o.unboxing_ai_status,o.unboxing_ai_confidence,o.unboxing_ai_summary,o.unboxing_ai_json)}</div></div>${o.evidence_match_status?`<div class="notice ${o.evidence_match_status==='Verified'?'good':o.evidence_match_status==='Mismatch'?'bad':'warn'}"><strong>Packing ↔ Unboxing cross-check: ${esc(o.evidence_match_status)}</strong></div>`:''}${o.ship_to?`<div class="notice good" style="margin-top:8px"><strong>${L('Ship to','จัดส่งถึง')}</strong><div class="sub">${esc(o.ship_to.name)} · ${esc(o.ship_to.phone)}<br>${esc(o.ship_to.line1)}${o.ship_to.district?', '+esc(o.ship_to.district):''}, ${esc(o.ship_to.city)}, ${esc(o.ship_to.province)} ${esc(o.ship_to.postal)}</div></div>`:`<div class="notice warn" style="margin-top:8px">${L('Waiting for the buyer\'s payment. The delivery address appears once they pay.','รอผู้ซื้อชำระเงิน ที่อยู่จัดส่งจะแสดงหลังชำระเงิน')}</div>`}<div class="toolbar">${!o.packing_video_url?`<button class="btn btn-blue" onclick="openEvidenceRecorder(${o.id},'packing','seller-orders')">Record Packing Video</button>`:'<span class="sub">Packing video already submitted for this order.</span>'}</div>${o.packing_video_url&&o.ship_to?(o.tracking_number?`<div style="margin-top:8px">${L('Tracking','เลขพัสดุ')}: <strong>${esc(o.tracking_number)}</strong></div>`:`<div class="toolbar" style="margin-top:8px"><input id="trk-${o.id}" placeholder="${L('Tracking number','เลขพัสดุ')}" style="flex:1;min-width:150px"><button class="btn btn-primary" onclick="saveTracking(${o.id})">${L('Mark as shipped','ทำเครื่องหมายว่าจัดส่งแล้ว')}</button></div>`):''}</section>`).join('')||'<div class="empty">No orders yet for this store.</div>'}`}

const PACKING_STEPS=[
  'Show the full FRONT of the exact card clearly.',
  'Flip the SAME card and show the full BACK clearly.',
  'Show all EDGES, CORNERS and important surface details.',
  'Keep the card continuously in frame while sleeving, top-loading and placing it into the package. No cuts or switching.',
  'Show the SEALED package and shipping label/order number before ending the video.'
];
const UNBOXING_STEPS=[
  'Show the UNOPENED parcel and shipping label/order number.',
  'Keep the parcel continuously in frame while opening it. No cuts or pauses.',
  'Show the card immediately as it is removed from the package.',
  'Show the full FRONT of the received card clearly.',
  'Show the full BACK, then the EDGES/CORNERS and surface details before ending the video.'
];
function evidenceSteps(){return state.evidenceContext?.kind==='packing'?PACKING_STEPS:UNBOXING_STEPS}
function openEvidenceRecorder(orderId,kind,returnPage){if(kind==='unboxing'&&(needBuyer('orders')||needVerified()))return;stopEvidenceStream();state.evidenceContext={orderId,kind,returnPage:returnPage||'orders'};state.evidenceStep=0;state.evidenceBlob=null;if(state.evidenceReviewUrl){URL.revokeObjectURL(state.evidenceReviewUrl);state.evidenceReviewUrl=''}state.page='evidence-recorder';render()}
function evidenceRecorderPage(){const c=state.evidenceContext;if(!c)return ordersReady();const steps=evidenceSteps();const title=c.kind==='packing'?'Seller Packing Video':'Buyer Unboxing Video';const backPage=c.returnPage||'orders';const backLabel=backPage==='seller-orders'?'← Seller Orders':'← Orders';return shell(`<button class="ghost" onclick="stopEvidenceStream();setPage('${backPage}')">${backLabel}</button><div class="section-head"><div><h1 class="screen-title">${title}</h1><p>One continuous video. Follow every step so the card cannot be switched off-camera.</p></div></div><div class="grid-2 evidence-layout"><section class="panel blue"><div class="evidence-rule">● KEEP RECORDING · NO CUTS · JUST SHOW EACH STEP — THE AI ADVANCES IT FOR YOU</div><div class="video-stage">${state.evidenceReviewUrl?`<video class="evidence-video" src="${state.evidenceReviewUrl}" controls playsinline></video>`:`<video id="evidencePreview" class="evidence-video" autoplay muted playsinline></video><div id="cameraPlaceholder" class="camera-placeholder">Camera preview appears here</div>`}</div><div id="evidencePrompt" class="next-prompt"><small>STEP ${state.evidenceStep+1} OF ${steps.length}</small><strong>${esc(steps[state.evidenceStep])}</strong><div class="next-hint">${state.evidenceStep<steps.length-1?'Next: '+esc(steps[state.evidenceStep+1]):'Final step — keep recording until this is clearly shown.'}</div><div id="stepCheckBar" class="step-check-bar"></div></div><div class="toolbar evidence-controls">${!state.evidenceReviewUrl?`<button id="startEvidenceBtn" class="btn btn-primary" onclick="startGuidedRecording()">Start Guided Recording</button><button id="stopEvidenceBtn" class="btn btn-outline" onclick="stopGuidedRecording()" disabled>Stop & Review</button>`:`<button class="btn btn-outline" onclick="redoEvidence()">Record Again</button><button class="btn btn-primary" onclick="uploadGuidedEvidence()">Upload Required Video</button>`}</div></section><section class="panel yellow"><h2>${c.kind==='packing'?'Packing guide':'Unboxing guide'}</h2><div class="evidence-steps">${steps.map((step,i)=>`<div class="evidence-step ${i<state.evidenceStep?'done':i===state.evidenceStep?'active':''}"><span>${i+1}</span><div>${esc(step)}</div></div>`).join('')}</div><div class="notice warn"><strong>Why this matters:</strong> front, back and the full packing/unboxing sequence remain linked in one continuous video, reducing the chance of swapping a genuine and counterfeit card.</div><div class="notice"><strong>Recording must be done here in the app.</strong> Uploading a video file from your gallery is not accepted, so the recording can't be pre-edited or swapped before it reaches Collectra. If the camera won't open, make sure you allowed camera/microphone permission and are using HTTPS or localhost.</div></section></div>`)}
async function startGuidedRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('In-app recording needs camera permission and HTTPS (or localhost). Please enable camera access and try again.');return}try{state.evidenceStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:true});const video=$('#evidencePreview');video.srcObject=state.evidenceStream;$('#cameraPlaceholder')?.remove();const supported=['video/mp4','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));const opts={videoBitsPerSecond:1800000};if(supported)opts.mimeType=supported;state.evidenceChunks=[];state.evidenceRecorder=new MediaRecorder(state.evidenceStream,opts);state.evidenceRecorder.ondataavailable=e=>{if(e.data?.size)state.evidenceChunks.push(e.data)};state.evidenceRecorder.onstop=()=>{const type=state.evidenceRecorder?.mimeType||'video/webm';state.evidenceBlob=new Blob(state.evidenceChunks,{type});state.evidenceReviewUrl=URL.createObjectURL(state.evidenceBlob);stopEvidenceStream();render()};state.evidenceRecorder.start(800);state.evidenceStartedAt=Date.now();state.evidenceStep=0;$('#startEvidenceBtn').disabled=true;$('#startEvidenceBtn').textContent='Recording…';$('#stopEvidenceBtn').disabled=true;updateEvidenceUI();startStepPolling()}catch(e){console.error(e);toast('Camera could not start. Check camera/microphone permission and try again.') }}
function captureEvidenceFrame(){const video=$('#evidencePreview');if(!video||!video.videoWidth)return null;const canvas=document.createElement('canvas');const scale=Math.min(1,480/video.videoWidth);canvas.width=video.videoWidth*scale;canvas.height=video.videoHeight*scale;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);return new Promise(res=>canvas.toBlob(b=>res(b),'image/jpeg',0.6))}
async function fetchStepCheck(stepText){try{const blob=await captureEvidenceFrame();if(!blob)return null;const fd=new FormData();fd.append('frame',blob,'frame.jpg');fd.append('step_text',stepText);fd.append('kind',state.evidenceContext?.kind||'packing');return await api('/api/evidence-step-check',{method:'POST',body:fd})}catch(e){return null}}
function setStepStatus(mode,text){const bar=$('#stepCheckBar');if(!bar)return;bar.className='step-check-bar'+(mode?' '+mode:'');bar.textContent=text||''}
function startStepPolling(){stopStepPolling();state.evidencePolling=setInterval(pollCurrentStep,1800)}
function stopStepPolling(){if(state.evidencePolling){clearInterval(state.evidencePolling);state.evidencePolling=null}state.evidenceChecking=false}
async function pollCurrentStep(){if(state.evidenceChecking)return;if(!state.evidenceRecorder||state.evidenceRecorder.state!=='recording'){stopStepPolling();return}const steps=evidenceSteps();const stepIndex=state.evidenceStep;const stepText=steps[stepIndex];state.evidenceChecking=true;setStepStatus('checking','Checking…');const r=await fetchStepCheck(stepText);state.evidenceChecking=false;if(state.evidenceStep!==stepIndex||!state.evidenceRecorder||state.evidenceRecorder.state!=='recording')return;if(!r){setStepStatus('','');return}if(r.ok){setStepStatus('ok','✓ Got it — hold steady…');if(stepIndex<steps.length-1){setTimeout(()=>{if(state.evidenceStep===stepIndex){state.evidenceStep++;updateEvidenceUI()}},700)}else{stopStepPolling();const btn=$('#stopEvidenceBtn');if(btn){btn.disabled=false;btn.classList.add('pulse')}setStepStatus('ok','✓ All steps shown — tap Stop & Review when ready')}}else{setStepStatus('warn','⚠ '+(r.message||'Adjust framing for this step'))}}
function skipEvidenceStep(){const steps=evidenceSteps();if(!state.evidenceRecorder||state.evidenceRecorder.state!=='recording')return toast('Start recording first');if(state.evidenceStep<steps.length-1){state.evidenceStep++;updateEvidenceUI()}else{stopStepPolling();const btn=$('#stopEvidenceBtn');if(btn)btn.disabled=false}}
function updateEvidenceUI(){const steps=evidenceSteps(),p=$('#evidencePrompt');const recording=state.evidenceRecorder&&state.evidenceRecorder.state==='recording';if(p)p.innerHTML=`<small>STEP ${state.evidenceStep+1} OF ${steps.length}</small><strong>${esc(steps[state.evidenceStep])}</strong><div class="next-hint">${state.evidenceStep<steps.length-1?'Next: '+esc(steps[state.evidenceStep+1]):'Final step — keep recording until this is clearly shown.'}</div><div id="stepCheckBar" class="step-check-bar"></div>${recording?`<button class="skip-step-link" onclick="skipEvidenceStep()">Not detecting it? Skip this step →</button>`:''}`;$$('.evidence-step').forEach((el,i)=>{el.classList.toggle('done',i<state.evidenceStep);el.classList.toggle('active',i===state.evidenceStep)})}
function stopGuidedRecording(){if(!state.evidenceRecorder||state.evidenceRecorder.state!=='recording')return;if(state.evidenceStep<evidenceSteps().length-1)return toast('Keep recording — the AI hasn\'t confirmed every step yet');if(Date.now()-state.evidenceStartedAt<10000)return toast('Keep recording long enough to clearly show every step');stopStepPolling();state.evidenceRecorder.stop()}
function stopEvidenceStream(){stopStepPolling();if(state.evidenceStream){state.evidenceStream.getTracks().forEach(t=>t.stop());state.evidenceStream=null}}
function redoEvidence(){stopStepPolling();stopEvidenceStream();if(state.evidenceReviewUrl)URL.revokeObjectURL(state.evidenceReviewUrl);state.evidenceReviewUrl='';state.evidenceBlob=null;state.evidenceStep=0;render()}
async function uploadGuidedEvidence(){const c=state.evidenceContext;if(!c||!state.evidenceBlob)return toast('Record or choose the required video first');if(c.kind==='packing'&&!state.sellerSession){setPage('seller-login');return toast(L('Please log in as a seller first','กรุณาเข้าสู่ระบบผู้ขายก่อน'))}const steps=evidenceSteps();const ext=state.evidenceBlob.type.includes('mp4')?'mp4':'webm';const file=state.evidenceBlob instanceof File?state.evidenceBlob:new File([state.evidenceBlob],`${c.kind}-order-${c.orderId}.${ext}`,{type:state.evidenceBlob.type||'video/webm'});const fd=new FormData();fd.append('order_id',c.orderId);fd.append('kind',c.kind);fd.append('guide_steps',JSON.stringify(steps));fd.append('evidence',file);try{const r=await api('/api/order-evidence',{method:'POST',body:fd,headers:c.kind==='packing'?sellerHeaders():{}});const label=c.kind==='packing'?'Packing':'Unboxing';toast(r.ai?.status?`${label} video uploaded — AI: ${r.ai.status}`:`${label} video uploaded`);state.evidenceBlob=null;if(state.evidenceReviewUrl)URL.revokeObjectURL(state.evidenceReviewUrl);state.evidenceReviewUrl='';state.evidenceContext=null;if(c.returnPage==='seller-orders')sellerOrders();else orders()}catch(e){if(c.kind==='packing'&&/log in/i.test(e.message))return sellerSessionExpired(e.message);toast(e.message)}}

function admin(){return shell(`<div class="section-head"><div><h1 class="screen-title">Collectra Admin</h1><p>Hidden prototype area for seller approvals, human tickets and reference cards.</p></div></div><section class="panel"><div class="field"><label>Admin key</label><input id="adminKey" type="password" value="${esc(state.adminKey)}"><button class="btn btn-blue" style="margin-top:10px" onclick="loadAdmin()">Open Dashboard</button></div><div id="adminBody"></div></section>`)}
async function loadAdmin(){state.adminKey=$('#adminKey').value;localStorage.setItem('collectra_admin_key',state.adminKey);try{state._admin=await api('/api/admin/dashboard',{headers:{'X-Admin-Key':state.adminKey}});renderAdminBody()}catch(e){toast(e.message)}}
function renderAdminBody(){const d=state._admin, el=$('#adminBody');if(!d||!el)return;el.innerHTML=`<div class="admin-grid" style="margin-top:20px"><section><h2>Seller Applications</h2><p class="sub">Open the ID photos and check: the face on the ID matches the selfie, the code on the paper is visible, and the name and ID number match what they typed.</p>${d.applications.map(a=>{const ai=a.id_ai,c=ai&&ai.checks,m=(v,t)=>`<div class="sub">${v==='yes'?'✅':v==='no'?'❌':'❔'} ${t}</div>`;const hint=ai?(c?`<div class="notice ${ai.status==='looks_ok'?'good':'warn'}" style="margin-top:8px"><strong>Automatic hints (not a decision): ${esc(ai.status.replace('_',' '))}</strong>${m(c.code_matches,'Code on paper matches')}${m(c.id_number_matches,'ID number on card matches')}${m(c.name_matches,'Name on card matches')}${m(c.live_person,'Selfie shows a live person')}${m(c.holds_card,'Person is holding the card')}${m(c.card_genuine,'Card looks genuine')}${c.copy_suspected?'<div class="sub">❌ Looks like a screen or paper copy</div>':''}${ai.notes?`<div class="sub">${esc(ai.notes)}</div>`:''}</div>`:`<div class="sub" style="margin-top:6px">${esc(ai.note||'')}</div>`):'';return `<div class="admin-row" style="display:block"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><strong>${esc(a.full_name)}</strong> · ${esc(a.shop_name)}<div class="sub">${esc(a.email)} · ${esc(a.phone||'no phone')} · ID ends ${esc(a.id_last4)}</div></div><span class="badge">${esc(a.status)}</span></div><div class="sub" style="margin-top:6px">${a.email_verified?'✅ Email confirmed':'⚠️ Email NOT confirmed yet'}</div>${a.reset_requested_at?`<div class="notice warn" style="margin-top:8px">Password reset requested ${new Date(a.reset_requested_at).toLocaleString()}</div>`:''}<div class="sub" style="margin-top:6px">Code to look for in the selfie: <strong style="font-size:18px">${esc(a.id_challenge||'-')}</strong> · Selfie: ${a.selfie_source==='camera'?'live camera':'⚠️ chosen from files'} · ID photo: ${a.id_source==='camera'?'live camera':'⚠️ chosen from files'}</div>${hint}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn btn-outline" onclick="viewSellerId(${a.id})">View ID photos</button>${a.status==='pending'&&!a.email_verified?`<button class="btn btn-outline" onclick="createVerifyLink('seller',${a.id})">Create verification link</button><button class="btn btn-outline" onclick="decideSeller(${a.id},false)">Reject</button>`:''}${a.status==='pending'&&a.email_verified?`<button class="btn btn-primary" onclick="decideSeller(${a.id},true)">Approve</button><button class="btn btn-outline" onclick="decideSeller(${a.id},false)">Reject</button>`:''}${a.status==='approved'?`<button class="btn btn-outline" onclick="createResetLink(${a.id})">Create reset link</button>`:''}</div>${a.reject_reason?`<div class="sub" style="margin-top:6px">Reason: ${esc(a.reject_reason)}</div>`:''}<div id="idview-${a.id}"></div></div>`}).join('')||'None'}</section><section><h2>Buyers</h2><p class="sub">Accounts that asked for a password reset are listed first.</p>${(d.buyers||[]).map(b=>`<div class="admin-row"><div class="grow"><strong>${esc(b.full_name)}</strong><div class="sub">${esc(b.email)}${b.email_verified?'':' · <strong>email not confirmed</strong>'}${b.reset_requested_at?' · <strong>reset requested</strong>':''}</div></div>${b.email_verified?'':`<button class="btn btn-outline" onclick="createVerifyLink('buyer',${b.id})">Verify link</button>`}<button class="btn btn-outline" onclick="createBuyerResetLink(${b.id})">Reset link</button></div>`).join('')||'No buyers yet.'}</section><section><h2>Stores</h2>${(d.stores||[]).map(s=>`<div class="admin-row"><div class="grow"><strong>${esc(s.name)}</strong>${s.verified?' <span class="badge">Verified</span>':''}</div></div>`).join('')||'No stores yet.'}</section><section><h2>Human Support</h2>${d.tickets.map(t=>`<div class="admin-row"><div><strong>${esc(t.email||'No email')}</strong><div>${esc(t.message)}</div></div></div>`).join('')||'None'}</section><section><h2>AI Review Queue</h2>${d.verifications.map(v=>`<div class="admin-row"><div class="grow"><strong>${esc(v.verdict)} · ${v.confidence}/100</strong><div class="sub">${esc(v.category)} ${esc(v.card_name)}</div></div></div>`).join('')||'None'}</section><section><h2>Add Verified Reference</h2><form id="refForm" class="form-grid" onsubmit="uploadReference(event)"><div class="field"><label>Category</label><select name="category"><option>K-pop</option><option>T-pop</option><option>Other</option></select></div><div class="field"><label>Card name</label><input name="card_name"></div><div class="field"><label>Set / release</label><input name="set_name"></div><div class="field"><label>Verified reference image</label><input name="image" type="file" accept="image/*" required></div><button class="btn btn-blue">Upload Reference</button></form></section></div>`}
async function viewSellerId(id){const box=$('#idview-'+id);box.innerHTML='<p class="sub">Loading…</p>';try{const imgs=[];for(const w of['front','selfie']){const r=await fetch(`/api/admin/seller-id?seller_id=${id}&which=${w}`,{headers:{'X-Admin-Key':state.adminKey}});if(!r.ok)throw new Error('Could not load the ID photo');imgs.push(URL.createObjectURL(await r.blob()))}box.innerHTML=`<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:10px">${imgs.map((u,i)=>`<figure style="margin:0;flex:1;min-width:140px"><img src="${u}" style="width:100%;border-radius:10px;border:1px solid #cfd8f0" alt=""><figcaption class="sub">${i?'Selfie with ID':'ID front'}</figcaption></figure>`).join('')}</div>`}catch(e){box.innerHTML=`<div class="notice bad">${esc(e.message)}</div>`}}
async function decideSeller(id,approve){let reason='';if(approve){if(!confirm('Approve only if ALL are true:\n1. The face on the ID matches the selfie\n2. The code on the paper is visible in the selfie\n3. The name and ID number match what they typed\n\nApprove this seller?'))return}else{reason=prompt('Reason for rejecting (shown to the seller):','')||''}try{await api('/api/admin/seller-decision',{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':state.adminKey},body:JSON.stringify({seller_id:id,approve,reason})});toast(approve?'Seller approved':'Seller rejected');loadAdmin()}catch(e){toast(e.message)}}
async function createResetLink(id){try{const r=await api('/api/admin/seller-reset-link',{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':state.adminKey},body:JSON.stringify({seller_id:id})});try{await navigator.clipboard.writeText(r.link)}catch{}prompt('Send this link to the seller after confirming it is really them (valid '+r.expires_in_hours+' hours, works once). It is also copied.',r.link);loadAdmin()}catch(e){toast(e.message)}}
async function createBuyerResetLink(id){try{const r=await api('/api/admin/buyer-reset-link',{method:'POST',headers:{'Content-Type':'application/json','X-Admin-Key':state.adminKey},body:JSON.stringify({buyer_id:id}),quiet:true});try{await navigator.clipboard.writeText(r.link)}catch{}prompt('Send this link to the buyer after confirming it is really them (valid '+r.expires_in_hours+' hours, works once). It is also copied.',r.link);loadAdmin()}catch(e){toast(e.message)}}
async function uploadReference(e){e.preventDefault();const fd=new FormData(e.target);const r=await api('/api/admin/reference',{method:'POST',headers:{'X-Admin-Key':state.adminKey},body:fd});toast('Reference uploaded');e.target.reset();loadAdmin()}

function render(){let html='';switch(state.page.split('/')[0]){case'home':html=home();break;case'shops':html=shops();break;case'store':html=storePage();break;case'verify':html=verify();break;case'saved':html=saved();break;case'sell':html=sell();break;case'seller-login':html=sellerLoginPage();break;case'seller-register':html=sellerRegisterPage();break;case'buyer-login':html=buyerLoginPage();break;case'verify-email':html=verifyEmailPage(state.page.split('/')[1]||'');break;case'buyer-register':html=buyerRegisterPage();break;case'buyer-forgot':html=buyerForgotPage();break;case'buyer-reset':html=buyerResetPage(state.page.split('/')[1]||'');break;case'seller-forgot':html=sellerForgotPage();break;case'seller-reset':html=sellerResetPage(state.page.split('/')[1]||'');break;case'seller-dashboard':html=sellerDashboardPage();break;case'seller-tools':html=sellerTools();break;case'support':html=support();break;case'cart':html=cart();break;case'checkout':checkout();return;case'checkout-ready':html=checkoutReady();break;case'profile':html=profile();break;case'addresses':addresses();return;case'addresses-ready':html=addressesReady();break;case'orders':orders();return;case'orders-ready':html=ordersReady();break;case'seller-orders':html=sellerOrdersPage();if(state.sellerSession)sellerOrders();break;case'evidence-recorder':html=evidenceRecorderPage();break;case'admin':html=admin();break;default:state.page='home';html=home()}$('#app').innerHTML=html;if(state.page==='admin'&&state._admin)renderAdminBody()}
bootstrap();

async function submitBuyerCode(){const code=($('#bvCode')||{}).value||'';if(code.length!==6)return toast(L('Enter the 6-digit code from your email','กรอกรหัส 6 หลักจากอีเมล'));try{const r=await api('/api/buyer/verify-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code}),quiet:true});toast(r.message);await refreshBuyer();render()}catch(e){toast(e.message)}}
async function submitSellerCode(){const email=($('#slEmail').value||'').trim(),password=$('#slPassword').value||'',code=($('#slCode').value||'').trim();if(!email||!password)return toast(L('Enter your email and password above first','กรอกอีเมลและรหัสผ่านด้านบนก่อน'));if(code.length!==6)return toast(L('Enter the 6-digit code from your email','กรอกรหัส 6 หลักจากอีเมล'));try{const r=await api('/api/seller/verify-code',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,code}),quiet:true});toast(r.message)}catch(e){toast(e.message)}}
